SELECT u.id, q.amount FROM users u CROSS JOIN LATERAL (SELECT o.amount, o.id FROM orders o WHERE o.user_id = u.id AND o.amount >= 20) q ORDER BY u.id, q.id;
SELECT u.id, q.amount FROM users u LEFT JOIN LATERAL (SELECT o.amount, o.id FROM orders o WHERE o.user_id = u.id AND o.amount >= 20) q ON TRUE ORDER BY u.id, q.id;
SELECT u.id, q.next_age FROM users u CROSS JOIN LATERAL (SELECT u.age + 1 AS next_age) q ORDER BY u.id;
SELECT u.id, q.total FROM users u JOIN LATERAL (SELECT COUNT(*) AS total FROM orders o WHERE o.user_id = u.id AND o.amount > 10) q ON TRUE ORDER BY u.id;
SELECT u.id, q.total FROM users u CROSS JOIN LATERAL (SELECT SUM(o.amount) AS total FROM orders o WHERE o.user_id = u.id AND o.amount > 10) q ORDER BY u.id;
SELECT u.id, q.amount FROM users u LEFT JOIN LATERAL (SELECT o.amount FROM orders o WHERE o.user_id = u.id ORDER BY o.amount DESC, o.id LIMIT 1) q ON TRUE ORDER BY u.id, q.amount;
SELECT u.id, q.id, q.status FROM users u CROSS JOIN LATERAL (SELECT o.id, o.status FROM orders o WHERE o.user_id = u.id AND u.city <> 'Paris') q ORDER BY u.id, q.id;
SELECT d.id, q.id FROM departments d JOIN LATERAL (SELECT e.id FROM employees e WHERE e.department_id = d.id AND e.salary >= 15) q ON q.id > 0 ORDER BY d.id, q.id;
SELECT u.id, q.id FROM users u CROSS JOIN LATERAL (SELECT f.id FROM flags f WHERE f.id <= 1) q ORDER BY u.id, q.id;
SELECT u.id, a.x, b.y FROM users u CROSS JOIN LATERAL (SELECT u.age + 1 AS x) a CROSS JOIN LATERAL (SELECT a.x * 2 AS y) b ORDER BY u.id;
